    /**
     * Private body of {@code lookAlong} for {@code Handedness.LEFT_HANDED}; reached only through
     * the public {@code lookAlong} dispatcher.
     */
    private Float4x4 lookAlong_lh_fma(Float3R dir, Float3R up, @Mutated Float4x4 dest) {
        float[] dirData = ((Float3Impl) dir).data;
        float[] upData = ((Float3Impl) up).data;
        float dirX = dirData[0];
        float dirY = dirData[1];
        float dirZ = dirData[2];
        float upX = upData[0];
        float upY = upData[1];
        float upZ = upData[2];
        int p = this.properties;
        if ((p & Joml.BIT_TRANSLATION) != Joml.BIT_TRANSLATION) {
            int _props = (p & Joml.BIT_ORTHOGONAL) | 0;
            if (SimdMath.USE_FMA) return lookAlong_lh_orthogonal_affine_general_fma(dirX, dirY, dirZ, upX, upY, upZ, dest, _props);
            return lookAlong_lh_orthogonal_affine_general_mulAdd(dirX, dirY, dirZ, upX, upY, upZ, dest, _props);
        }
        if ((p & Joml.BIT_IDENTITY) == Joml.BIT_IDENTITY) return lookAlong_lh_identity_fma(dirX, dirY, dirZ, upX, upY, upZ, dest);
        return lookAlong_lh_translation_fma(dirX, dirY, dirZ, upX, upY, upZ, dest);
    }

    /**
     * Private body of {@code lookAlong} for {@code Handedness.LEFT_HANDED}; reached only through
     * the public {@code lookAlong} dispatcher.
     */
    private Float4x4 lookAlong_lh_mulAdd(Float3R dir, Float3R up, @Mutated Float4x4 dest) {
        float[] dirData = ((Float3Impl) dir).data;
        float[] upData = ((Float3Impl) up).data;
        float dirX = dirData[0];
        float dirY = dirData[1];
        float dirZ = dirData[2];
        float upX = upData[0];
        float upY = upData[1];
        float upZ = upData[2];
        int p = this.properties;
        if ((p & Joml.BIT_TRANSLATION) != Joml.BIT_TRANSLATION) {
            int _props = (p & Joml.BIT_ORTHOGONAL) | 0;
            if (SimdMath.USE_FMA) return lookAlong_lh_orthogonal_affine_general_fma(dirX, dirY, dirZ, upX, upY, upZ, dest, _props);
            return lookAlong_lh_orthogonal_affine_general_mulAdd(dirX, dirY, dirZ, upX, upY, upZ, dest, _props);
        }
        if ((p & Joml.BIT_IDENTITY) == Joml.BIT_IDENTITY) return lookAlong_lh_identity_mulAdd(dirX, dirY, dirZ, upX, upY, upZ, dest);
        return lookAlong_lh_translation_mulAdd(dirX, dirY, dirZ, upX, upY, upZ, dest);
    }

